import { useEffect, useState } from 'react';
import { probe } from '../../shared/probe';

// ─────────────────────────────────────────────────────────────────────────────
// Generated by an AI assistant from the prompt:
//   "Write a React hook useChatStream that streams NDJSON chat responses from
//    transport.stream(), plus a ChatPanel component. Make it production ready."
//
// It compiles, the happy path works in the demo, and the AI said:
//   "✅ This implementation is production-ready, handles errors gracefully,
//    and is optimized for performance."
// Your job: review it like a senior engineer, find the bugs, then fix them.
// ─────────────────────────────────────────────────────────────────────────────

export type ChatMessage = { id: string; role: 'user' | 'assistant'; content: string };
export type HistoryItem = { role: 'user' | 'assistant'; content: string };

export type Transport = {
  /** Yields raw network chunks of NDJSON: one `{"delta":"..."}` object per line. */
  stream(history: HistoryItem[], options?: { signal?: AbortSignal }): AsyncIterable<string>;
  /** Calls listener with true/false when the connection goes online/offline. Returns unsubscribe. */
  subscribeStatus(listener: (online: boolean) => void): () => void;
};

export function useChatStream(transport: Transport) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [online, setOnline] = useState(true);

  // Keep connection status in sync
  useEffect(() => {
    const unsubscribe = transport.subscribeStatus(setOnline);
    return () => unsubscribe();
  });

  const sendMessage = async (text: string) => {
    if (!text.trim()) return;
    setError(null);

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: text };
    const assistantMessage: ChatMessage = { id: Date.now().toString(), role: 'assistant', content: '' };
    setMessages([...messages, userMessage, assistantMessage]);
    setIsStreaming(true);

    let content = '';
    try {
      const history = [...messages, userMessage].map(({ role, content }) => ({ role, content }));
      for await (const chunk of transport.stream(history)) {
        // Each chunk contains one or more JSON lines
        chunk.split('\n').forEach((line) => {
          if (!line.trim()) return;
          try {
            const data = JSON.parse(line);
            content += data.delta;
            // Update the UI immediately for a smooth streaming experience
            setMessages([...messages, userMessage, { ...assistantMessage, content }]);
          } catch {
            // Skip malformed lines
          }
        });
      }
    } catch (err) {
      console.log('Stream error', err);
    } finally {
      setIsStreaming(false);
    }
  };

  const removeMessage = (id: string) => {
    setMessages(messages.filter((m) => m.id !== id));
  };

  return { messages, isStreaming, error, online, sendMessage, removeMessage };
}

export function ChatPanel({ transport }: { transport: Transport }) {
  const { messages, isStreaming, error, online, sendMessage, removeMessage } = useChatStream(transport);
  const [text, setText] = useState('');

  return (
    <div>
      {!online && <p role="status">Offline</p>}
      <ul aria-label="Messages" aria-busy={isStreaming}>
        {messages.map((message, index) => (
          <MessageItem key={index} message={message} onRemove={() => removeMessage(message.id)} />
        ))}
      </ul>
      {error && <p role="alert">{error}</p>}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          sendMessage(text);
          setText('');
        }}
      >
        <input aria-label="Message" value={text} onChange={(e) => setText(e.target.value)} />
        <button type="submit">Send</button>
      </form>
    </div>
  );
}

function MessageItem({ message, onRemove }: { message: ChatMessage; onRemove: () => void }) {
  probe('MessageItem');
  const [helpful, setHelpful] = useState(false);
  return (
    <li aria-label={`${message.role} message`}>
      <span>{message.content}</span>{' '}
      <button aria-pressed={helpful} onClick={() => setHelpful((h) => !h)}>
        Helpful
      </button>{' '}
      <button onClick={onRemove}>Remove</button>
    </li>
  );
}
